<!DOCTYPE html>
<html lang="hu">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
    <meta name="apple-mobile-web-app-capable" content="yes">
    <meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">
    <title>Chat Interface</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
            -webkit-tap-highlight-color: transparent;
        }

        :root {
            --glass-bg: rgba(255, 255, 255, 0.08);
            --glass-border: rgba(255, 255, 255, 0.18);
            --glass-shadow: rgba(0, 0, 0, 0.1);
            --tint-primary: rgba(0, 122, 255, 0.8);
            --tint-success: rgba(52, 199, 89, 0.8);
            --tint-warning: rgba(255, 149, 0, 0.8);
            --tint-danger: rgba(255, 59, 48, 0.8);
            --text-primary: rgba(255, 255, 255, 0.95);
            --text-secondary: rgba(255, 255, 255, 0.65);
            --blur-amount: 40px;
            --transition-fluid: cubic-bezier(0.4, 0.0, 0.2, 1);
        }

        [data-theme="light"] {
            --glass-bg: rgba(255, 255, 255, 0.6);
            --glass-border: rgba(255, 255, 255, 0.9);
            --glass-shadow: rgba(0, 0, 0, 0.05);
            --text-primary: rgba(0, 0, 0, 0.9);
            --text-secondary: rgba(0, 0, 0, 0.6);
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'SF Pro Text', system-ui, sans-serif;
            background: #000000;
            min-height: 100vh;
            color: var(--text-primary);
            overflow-x: hidden;
        }

        .wallpaper-layer {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background-image: 
                radial-gradient(circle at 20% 30%, rgba(0, 122, 255, 0.15) 0%, transparent 50%),
                radial-gradient(circle at 80% 70%, rgba(52, 199, 89, 0.1) 0%, transparent 50%),
                radial-gradient(circle at 50% 50%, rgba(175, 82, 222, 0.12) 0%, transparent 50%);
            pointer-events: none;
            z-index: 0;
            animation: wallpaperShift 30s ease-in-out infinite;
        }

        @keyframes wallpaperShift {
            0%, 100% { transform: translate(0, 0) scale(1); }
            33% { transform: translate(-20px, 30px) scale(1.05); }
            66% { transform: translate(20px, -20px) scale(0.95); }
        }

        .glass-container {
            backdrop-filter: blur(var(--blur-amount)) saturate(180%);
            -webkit-backdrop-filter: blur(var(--blur-amount)) saturate(180%);
            background: var(--glass-bg);
            border: 1px solid var(--glass-border);
            border-radius: 24px;
            box-shadow: 
                0 8px 32px var(--glass-shadow),
                inset 0 1px 0 rgba(255, 255, 255, 0.1);
        }

        .glass-thick {
            backdrop-filter: blur(50px) saturate(200%);
            -webkit-backdrop-filter: blur(50px) saturate(200%);
            background: rgba(255, 255, 255, 0.12);
        }

        .glass-thin {
            backdrop-filter: blur(30px) saturate(160%);
            -webkit-backdrop-filter: blur(30px) saturate(160%);
            background: rgba(255, 255, 255, 0.06);
        }

        .top-bar {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            height: 88px;
            display: flex;
            align-items: flex-end;
            justify-content: space-between;
            padding: 0 12px 8px 12px;
            z-index: 1000;
            backdrop-filter: blur(50px) saturate(200%);
            -webkit-backdrop-filter: blur(50px) saturate(200%);
            background: rgba(0, 0, 0, 0.6);
            border-bottom: 1px solid rgba(255, 255, 255, 0.1);
        }

        .top-bar-title {
            font-size: 17px;
            font-weight: 600;
            text-align: center;
            flex: 1;
            margin: 0 12px;
        }

        .top-bar-btn {
            width: 32px;
            height: 32px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            transition: all 0.2s var(--transition-fluid);
            background: rgba(255, 255, 255, 0.1);
            border: 1px solid rgba(255, 255, 255, 0.2);
        }

        .top-bar-btn:active {
            transform: scale(0.95);
            background: rgba(255, 255, 255, 0.15);
        }

        .chat-area {
            position: fixed;
            top: 88px;
            left: 0;
            right: 0;
            bottom: 100px;
            overflow-y: auto;
            padding: 16px 12px;
            z-index: 1;
        }

        .message-bubble {
            max-width: 75%;
            padding: 12px 16px;
            margin-bottom: 12px;
            border-radius: 18px;
            word-wrap: break-word;
            animation: fadeIn 0.3s var(--transition-fluid);
        }

        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
        }

        .message-user {
            margin-left: auto;
            background: linear-gradient(135deg, rgba(0, 122, 255, 0.7), rgba(10, 132, 255, 0.8));
            border: 1px solid rgba(255, 255, 255, 0.3);
            text-align: right;
        }

        .message-assistant {
            margin-right: auto;
            background: rgba(255, 255, 255, 0.12);
            border: 1px solid rgba(255, 255, 255, 0.18);
        }

        .composer-bar {
            position: fixed;
            bottom: 0;
            left: 0;
            right: 0;
            padding: 12px;
            backdrop-filter: blur(50px) saturate(200%);
            -webkit-backdrop-filter: blur(50px) saturate(200%);
            background: rgba(0, 0, 0, 0.6);
            border-top: 1px solid rgba(255, 255, 255, 0.1);
            z-index: 1000;
        }

        .composer-container {
            display: flex;
            align-items: flex-end;
            gap: 8px;
        }

        .composer-input-wrapper {
            flex: 1;
            background: rgba(255, 255, 255, 0.12);
            border: 1px solid rgba(255, 255, 255, 0.2);
            border-radius: 20px;
            padding: 10px 16px;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .composer-input {
            flex: 1;
            background: transparent;
            border: none;
            outline: none;
            color: var(--text-primary);
            font-size: 16px;
            font-family: inherit;
            resize: none;
            max-height: 100px;
            overflow-y: auto;
        }

        .composer-input::placeholder {
            color: var(--text-secondary);
        }

        .composer-btn {
            width: 30px;
            height: 30px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            transition: all 0.2s var(--transition-fluid);
            background: rgba(255, 255, 255, 0.1);
            border: 1px solid rgba(255, 255, 255, 0.2);
            flex-shrink: 0;
        }

        .composer-btn:active {
            transform: scale(0.9);
        }

        .send-btn {
            width: 36px;
            height: 36px;
            border-radius: 50%;
            background: linear-gradient(135deg, rgba(0, 122, 255, 0.8), rgba(10, 132, 255, 0.9));
            border: 1px solid rgba(255, 255, 255, 0.3);
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            transition: all 0.2s var(--transition-fluid);
            flex-shrink: 0;
        }

        .send-btn:active {
            transform: scale(0.9);
        }

        .send-btn:disabled {
            opacity: 0.5;
            cursor: not-allowed;
        }

        .sidebar-overlay {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: rgba(0, 0, 0, 0.5);
            z-index: 2000;
            display: none;
            animation: fadeInOverlay 0.3s var(--transition-fluid);
        }

        @keyframes fadeInOverlay {
            from { opacity: 0; }
            to { opacity: 1; }
        }

        .sidebar-overlay.active {
            display: block;
        }

        .sidebar {
            position: fixed;
            top: 0;
            right: -320px;
            width: 320px;
            height: 100vh;
            background: rgba(0, 0, 0, 0.95);
            backdrop-filter: blur(50px) saturate(200%);
            -webkit-backdrop-filter: blur(50px) saturate(200%);
            border-left: 1px solid rgba(255, 255, 255, 0.1);
            z-index: 3000;
            transition: right 0.4s var(--transition-fluid);
            padding: 20px;
            overflow-y: auto;
        }

        .sidebar.active {
            right: 0;
        }

        .sidebar-header {
            font-size: 24px;
            font-weight: 700;
            margin-bottom: 24px;
            padding-bottom: 16px;
            border-bottom: 1px solid rgba(255, 255, 255, 0.1);
        }

        .sidebar-section {
            margin-bottom: 24px;
        }

        .sidebar-section-title {
            font-size: 14px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            opacity: 0.7;
            margin-bottom: 12px;
        }

        .sidebar-item {
            padding: 12px 16px;
            background: rgba(255, 255, 255, 0.08);
            border: 1px solid rgba(255, 255, 255, 0.15);
            border-radius: 12px;
            margin-bottom: 8px;
            cursor: pointer;
            transition: all 0.2s var(--transition-fluid);
        }

        .sidebar-item:active {
            transform: scale(0.98);
            background: rgba(255, 255, 255, 0.12);
        }

        .history-panel {
            position: fixed;
            bottom: -100%;
            left: 0;
            right: 0;
            height: 70vh;
            background: rgba(0, 0, 0, 0.95);
            backdrop-filter: blur(50px) saturate(200%);
            -webkit-backdrop-filter: blur(50px) saturate(200%);
            border-top: 1px solid rgba(255, 255, 255, 0.1);
            border-radius: 24px 24px 0 0;
            z-index: 2500;
            transition: bottom 0.4s var(--transition-fluid);
            padding: 24px;
            overflow-y: auto;
        }

        .history-panel.active {
            bottom: 0;
        }

        .history-handle {
            width: 40px;
            height: 4px;
            background: rgba(255, 255, 255, 0.3);
            border-radius: 2px;
            margin: 0 auto 20px;
        }

        .history-search {
            width: 100%;
            padding: 12px 16px;
            background: rgba(255, 255, 255, 0.1);
            border: 1px solid rgba(255, 255, 255, 0.2);
            border-radius: 16px;
            color: var(--text-primary);
            font-size: 16px;
            font-family: inherit;
            margin-bottom: 16px;
        }

        .history-search:focus {
            outline: none;
            background: rgba(255, 255, 255, 0.15);
            border-color: var(--tint-primary);
        }

        .history-item {
            padding: 16px;
            background: rgba(255, 255, 255, 0.08);
            border: 1px solid rgba(255, 255, 255, 0.15);
            border-radius: 12px;
            margin-bottom: 12px;
            cursor: pointer;
            transition: all 0.2s var(--transition-fluid);
        }

        .history-item:active {
            transform: scale(0.98);
            background: rgba(255, 255, 255, 0.12);
        }

        .history-item-title {
            font-size: 15px;
            font-weight: 600;
            margin-bottom: 6px;
        }

        .history-item-date {
            font-size: 12px;
            opacity: 0.6;
        }

        @media (max-width: 768px) {
            .message-bubble {
                max-width: 85%;
            }

            .sidebar {
                width: 85%;
                right: -85%;
            }

            .sidebar.active {
                right: 0;
            }
        }
    </style>
</head>
<body>
    <div class="wallpaper-layer"></div>

    <div class="top-bar">
        <div class="top-bar-btn" id="menuBtn">☰</div>
        <div class="top-bar-title">Chat</div>
        <div class="top-bar-btn" id="moreBtn">⋯</div>
    </div>

    <div class="chat-area" id="chatArea"></div>

    <div class="composer-bar">
        <div class="composer-container">
            <div class="composer-input-wrapper">
                <div class="composer-btn" id="attachBtn">+</div>
                <textarea class="composer-input" id="messageInput" rows="1" placeholder="Message"></textarea>
            </div>
            <div class="send-btn" id="sendBtn">→</div>
        </div>
    </div>

    <div class="sidebar-overlay" id="sidebarOverlay"></div>

    <div class="sidebar" id="sidebar">
        <div class="sidebar-header">Settings</div>
        <div class="sidebar-section">
            <div class="sidebar-section-title">Data Controls</div>
            <div class="sidebar-item" id="historyBtn">History</div>
            <div class="sidebar-item">Export Data</div>
        </div>
        <div class="sidebar-section">
            <div class="sidebar-section-title">Preferences</div>
            <div class="sidebar-item">Haptic Feedback</div>
            <div class="sidebar-item">Personalization</div>
        </div>
        <div class="sidebar-section">
            <div class="sidebar-section-title">Account</div>
            <div class="sidebar-item">Profile</div>
        </div>
    </div>

    <div class="history-panel" id="historyPanel">
        <div class="history-handle"></div>
        <input type="text" class="history-search" placeholder="Search conversations..." id="historySearch">
        <div id="historyList"></div>
    </div>

    <script>
        const chatArea = document.getElementById('chatArea');
        const messageInput = document.getElementById('messageInput');
        const sendBtn = document.getElementById('sendBtn');
        const menuBtn = document.getElementById('menuBtn');
        const moreBtn = document.getElementById('moreBtn');
        const sidebar = document.getElementById('sidebar');
        const sidebarOverlay = document.getElementById('sidebarOverlay');
        const historyBtn = document.getElementById('historyBtn');
        const historyPanel = document.getElementById('historyPanel');
        const historySearch = document.getElementById('historySearch');
        const historyList = document.getElementById('historyList');
        const attachBtn = document.getElementById('attachBtn');

        let messages = [];
        let conversations = [
            { id: 1, title: 'Previous conversation 1', date: '2 hours ago' },
            { id: 2, title: 'Previous conversation 2', date: 'Yesterday' },
            { id: 3, title: 'Previous conversation 3', date: '3 days ago' }
        ];

        function renderMessages() {
            chatArea.innerHTML = messages.map(msg => `
                <div class="message-bubble message-${msg.role}">
                    ${escapeHtml(msg.content)}
                </div>
            `).join('');
            chatArea.scrollTop = chatArea.scrollHeight;
        }

        function addMessage(role, content) {
            messages.push({ role, content });
            renderMessages();
        }

        function sendMessage() {
            const text = messageInput.value.trim();
            if (!text) return;

            addMessage('user', text);
            messageInput.value = '';
            messageInput.style.height = 'auto';

            setTimeout(() => {
                addMessage('assistant', 'This is a response message.');
            }, 500);
        }

        sendBtn.addEventListener('click', sendMessage);

        messageInput.addEventListener('keydown', (e) => {
            if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                sendMessage();
            }
        });

        messageInput.addEventListener('input', () => {
            messageInput.style.height = 'auto';
            messageInput.style.height = messageInput.scrollHeight + 'px';
        });

        moreBtn.addEventListener('click', () => {
            sidebar.classList.add('active');
            sidebarOverlay.classList.add('active');
        });

        sidebarOverlay.addEventListener('click', () => {
            sidebar.classList.remove('active');
            sidebarOverlay.classList.remove('active');
        });

        historyBtn.addEventListener('click', () => {
            sidebar.classList.remove('active');
            sidebarOverlay.classList.remove('active');
            historyPanel.classList.add('active');
            renderHistory();
        });

        historyPanel.addEventListener('click', (e) => {
            if (e.target === historyPanel) {
                historyPanel.classList.remove('active');
            }
        });

        function renderHistory() {
            historyList.innerHTML = conversations.map(conv => `
                <div class="history-item" data-id="${conv.id}">
                    <div class="history-item-title">${escapeHtml(conv.title)}</div>
                    <div class="history-item-date">${escapeHtml(conv.date)}</div>
                </div>
            `).join('');
        }

        historyList.addEventListener('click', (e) => {
            const item = e.target.closest('.history-item');
            if (item) {
                historyPanel.classList.remove('active');
                messages = [];
                addMessage('assistant', 'Loaded conversation: ' + item.querySelector('.history-item-title').textContent);
            }
        });

        historySearch.addEventListener('input', (e) => {
            const query = e.target.value.toLowerCase();
            const filtered = conversations.filter(conv => 
                conv.title.toLowerCase().includes(query)
            );
            historyList.innerHTML = filtered.map(conv => `
                <div class="history-item" data-id="${conv.id}">
                    <div class="history-item-title">${escapeHtml(conv.title)}</div>
                    <div class="history-item-date">${escapeHtml(conv.date)}</div>
                </div>
            `).join('');
        });

        attachBtn.addEventListener('click', () => {
            const fileInput = document.createElement('input');
            fileInput.type = 'file';
            fileInput.accept = 'image/*';
            fileInput.click();
        });

        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        addMessage('assistant', 'Hello! How can I help you today?');
    </script>
</body>
</html>
